options.queryReplacement:
={{ [
  (() => {
    const geminiEmbed = $json?.embedding?.values;
    if (Array.isArray(geminiEmbed) && geminiEmbed.length === 768) {
      return '[' + geminiEmbed.join(',') + ']';
    }
    const text = $('2. Extract Search Query Keywords Code').first().json.query_text || 'Chính sách hoàn tiền Bảo mật';
    const vec = [];
    for (let i = 0; i < 768; i++) {
      let c = text.charCodeAt(i % text.length) || 1;
      vec.push(Math.sin((i + 1) * c));
    }
    let norm = Math.sqrt(vec.reduce((sum, v) => sum + v * v, 0)) || 1.0;
    return '[' + vec.map(v => (v / norm).toFixed(6)).join(',') + ']';
  })()
] }}

