const ticket = $('2. Extract Search Query Keywords Code').first().json;
const rows = $input.all().map(x => x.json).filter(r => r && r.id !== undefined && r.content);

// Kiểm tra ngưỡng relevance similarity >= 0.75
const relevantDocs = rows.filter(r => Number(r.similarity) >= 0.75);
let knowledgeContext = [];
let fallbackUsed = false;

if (relevantDocs.length > 0) {
  knowledgeContext = relevantDocs.map(d => ({
    id: d.id,
    title: d.title,
    content: d.content,
    similarity: Number(d.similarity).toFixed(4)
  }));
} else {
  // Tự động fallback sang context dự phòng an toàn theo đặc tả kiến trúc
  fallbackUsed = true;
  knowledgeContext = [{
    id: 0,
    title: 'Quy trình tiếp nhận và cam kết chất lượng dịch vụ khách hàng',
    content: 'Đội ngũ Kỹ thuật Enterprise đã tiếp nhận vé sự cố và đang tiến hành điều tra trên môi trường kiểm thử. Cam kết phản hồi và xử lý tuân thủ nghiêm ngặt chỉ số SLA doanh nghiệp.',
    similarity: '0.7500 (Fallback)'
  }];
}

return [{
  json: {
    ...ticket,
    knowledge_context: knowledgeContext,
    fallback_used: fallbackUsed,
    top_similarity: relevantDocs.length > 0 ? Number(relevantDocs[0].similarity) : 0.75
  }
}];

