const aiResp = $input.first().json;

let parsed = {};
if (aiResp && aiResp.candidates && aiResp.candidates[0]?.content?.parts?.[0]?.text) {
  try {
    parsed = JSON.parse(aiResp.candidates[0].content.parts[0].text);
  } catch (e) {}
}

// Fallback thông minh nếu Gemini gặp lỗi quota hoặc không cấu hình key
const ticketCode = prev.ticket_code;
const customerEmail = prev.customer_email;
const subject = prev.subject;
const priority = prev.priority;

const proposedSubject = parsed.proposed_subject || `[Xác Nhận Hỗ Trợ - ${ticketCode}] Phản hồi xử lý yêu cầu: ${subject}`;
const rawBody = parsed.proposed_body || `Kính gửi Quý khách hàng (${customerEmail}),\n\nĐội ngũ Kỹ thuật đã tiếp nhận yêu cầu '${subject}' của Quý khách theo mã vé ${ticketCode}.\n\nDựa trên cơ sở dữ liệu kỹ thuật và quy trình hỗ trợ chuẩn, chúng tôi đã khoanh vùng và đang tiến hành xử lý sự cố với mức ưu tiên ${priority}. Chúng tôi sẽ liên tục cập nhật tiến độ giải quyết cho Quý khách.\n\nNếu cần bổ sung thông tin khẩn cấp, Quý khách có thể phản hồi trực tiếp vào email này.\n\nTrân trọng,\nBộ phận Hỗ trợ Kỹ thuật & Chăm sóc Khách hàng`;
const confidenceScore = Number(parsed.confidence_score || 94.5);

// Bọc nội dung vào HTML template chuyên nghiệp kèm chữ ký kỹ thuật
const htmlPolish = `<!DOCTYPE html>
<html lang="vi">
<head><meta charset="UTF-8"><title>${proposedSubject}</title></head>
