      <table role="presentation" width="640" cellspacing="0" cellpadding="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 20px 40px rgba(0,0,0,0.3);max-width:640px;width:100%;">
        <tr>
          <td style="background:linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%);padding:28px 40px;color:#ffffff;">
            <div style="font-size:11px;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:6px;opacity:0.9;">ENTERPRISE TECHNICAL SUPPORT</div>
            <h1 style="margin:0;font-size:20px;font-weight:bold;">THÔNG BÁO XỬ LÝ VÉ SỰ CỐ</h1>
            <div style="margin-top:8px;display:inline-block;padding:4px 12px;background:rgba(255,255,255,0.2);border-radius:20px;font-size:12px;font-family:monospace;">Mã vé: ${ticketCode} | Ưu tiên: ${priority}</div>
          </td>
        </tr>
        <tr>
          <td style="padding:32px 40px;">
            <div style="font-size:15px;line-height:1.7;color:#334155;">
              ${rawBody.replace(/\n\n/g, '<br><br>').replace(/\n/g, '<br>')}
            </div>
            <div style="margin-top:32px;padding-top:20px;border-top:1px solid #e2e8f0;font-size:13px;color:#64748b;">
              <strong style="color:#0f172a;">Trung Tâm Vận Hành & Hỗ Trợ Doanh Nghiệp</strong><br>
              Email: support@company.com &bull; Hotline: 1900-6868<br>
              Hệ thống giám sát SLA tự động &bull; Trạng thái vé: PENDING_APPROVAL
